mkitem!{mkenum!{#[doc = " This datastructure is used to represent the value of constants used in the type system."] #[doc = ""] #[doc = " We explicitly choose a different datastructure from the way values are processed within"] #[doc = " CTFE, as in the type system equal values (according to their `PartialEq`) must also have"] #[doc = " equal representation (`==` on the rustc data structure, e.g. `ValTree`) and vice versa."] #[doc = " Since CTFE uses `AllocId` to represent pointers, it often happens that two different"] #[doc = " `AllocId`s point to equal values. So we may end up with different representations for"] #[doc = " two constants whose value is `&42`. Furthermore any kind of struct that has padding will"] #[doc = " have arbitrary values within that padding, even if the values of the struct are the same."] #[doc = ""] #[doc = " `ValTree` does not have this problem with representation, as it only contains integers or"] #[doc = " lists of (nested) `ValTree`."] #[derive (Clone , Debug , Hash , Eq , PartialEq)] #[derive (HashStable , TyEncodable , TyDecodable)] pub enum ValTreeKind < 'tcx > { #[doc = " integers, `bool`, `char` are represented as scalars."] #[doc = " See the `ScalarInt` documentation for how `ScalarInt` guarantees that equal values"] #[doc = " of these types have the same representation."] Leaf (ScalarInt) , #[doc = " The fields of any kind of aggregate. Structs, tuples and arrays are represented by"] #[doc = " listing their fields' values in order."] #[doc = ""] #[doc = " Enums are represented by storing their variant index as a u32 field, followed by all"] #[doc = " the fields of the variant."] #[doc = ""] #[doc = " ZST types are represented as an empty slice."] Branch (Box < [ValTree < 'tcx >] >) , }}}
mkitem!{mkimpl!{impl < 'tcx > ValTreeKind < 'tcx > { #[inline] pub fn unwrap_leaf (& self) -> ScalarInt { match self { Self :: Leaf (s) => * s , _ => bug ! ("expected leaf, got {:?}" , self) , } } #[inline] pub fn unwrap_branch (& self) -> & [ValTree < 'tcx >] { match self { Self :: Branch (branch) => & * * branch , _ => bug ! ("expected branch, got {:?}" , self) , } } pub fn try_to_scalar (& self) -> Option < Scalar > { self . try_to_scalar_int () . map (Scalar :: Int) } pub fn try_to_scalar_int (& self) -> Option < ScalarInt > { match self { Self :: Leaf (s) => Some (* s) , Self :: Branch (_) => None , } } pub fn try_to_branch (& self) -> Option < & [ValTree < 'tcx >] > { match self { Self :: Branch (branch) => Some (& * * branch) , Self :: Leaf (_) => None , } } }}}
