mkitem!{mkimpl!{impl < 'tcx > ValTree < 'tcx > { #[doc = " Returns the zero-sized valtree: `Branch([])`."] pub fn zst (tcx : TyCtxt < 'tcx >) -> Self { tcx . consts . valtree_zst } pub fn is_zst (self) -> bool { matches ! (* self , ValTreeKind :: Branch (box [])) } pub fn from_raw_bytes (tcx : TyCtxt < 'tcx > , bytes : & [u8]) -> Self { let branches = bytes . iter () . map (| & b | Self :: from_scalar_int (tcx , b . into ())) ; Self :: from_branches (tcx , branches) } pub fn from_branches (tcx : TyCtxt < 'tcx > , branches : impl IntoIterator < Item = Self >) -> Self { tcx . intern_valtree (ValTreeKind :: Branch (branches . into_iter () . collect ())) } pub fn from_scalar_int (tcx : TyCtxt < 'tcx > , i : ScalarInt) -> Self { tcx . intern_valtree (ValTreeKind :: Leaf (i)) } }}}
