mkitem!{mkimpl!{impl < 'tcx > Value < 'tcx > { #[doc = " Attempts to extract the raw bits from the constant."] #[doc = ""] #[doc = " Fails if the value can't be represented as bits (e.g. because it is a reference"] #[doc = " or an aggregate)."] #[inline] pub fn try_to_bits (self , tcx : TyCtxt < 'tcx > , typing_env : ty :: TypingEnv < 'tcx >) -> Option < u128 > { let (ty :: Bool | ty :: Char | ty :: Uint (_) | ty :: Int (_) | ty :: Float (_)) = self . ty . kind () else { return None ; } ; let scalar = self . valtree . try_to_scalar_int () ? ; let input = typing_env . with_post_analysis_normalized (tcx) . as_query_input (self . ty) ; let size = tcx . layout_of (input) . ok () ? . size ; Some (scalar . to_bits (size)) } pub fn try_to_bool (self) -> Option < bool > { if ! self . ty . is_bool () { return None ; } self . valtree . try_to_scalar_int () ? . try_to_bool () . ok () } pub fn try_to_target_usize (self , tcx : TyCtxt < 'tcx >) -> Option < u64 > { if ! self . ty . is_usize () { return None ; } self . valtree . try_to_scalar_int () . map (| s | s . to_target_usize (tcx)) } #[doc = " Get the values inside the ValTree as a slice of bytes. This only works for"] #[doc = " constants with types &str, &[u8], or [u8; _]."] pub fn try_to_raw_bytes (self , tcx : TyCtxt < 'tcx >) -> Option < & 'tcx [u8] > { match self . ty . kind () { ty :: Ref (_ , inner_ty , _) => match inner_ty . kind () { ty :: Str => { } ty :: Slice (slice_ty) if * slice_ty == tcx . types . u8 => { } _ => return None , } , ty :: Array (array_ty , _) if * array_ty == tcx . types . u8 => { } _ => return None , } Some (tcx . arena . alloc_from_iter (self . valtree . unwrap_branch () . into_iter () . map (| v | v . unwrap_leaf () . to_u8 ()) ,)) } }}}
